class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        seen = set()
        left = best = 0
        for right, ch in enumerate(s):
            while ch in seen:
                seen.remove(s[left])
                left += 1
            seen.add(ch)
            best = max(best, right - left + 1)
        return best

class Solution:
    def characterReplacement(self, s: str, k: int) -> int:
        counts = {}
        left = max_f = best = 0
        for right, ch in enumerate(s):
            counts[ch] = counts.get(ch, 0) + 1
            max_f = max(max_f, counts[ch])
            if (right - left + 1) - max_f > k:
                counts[s[left]] -= 1
                left += 1
            best = max(best, right - left + 1)
        return best

class Solution:
    def checkInclusion(self, s1: str, s2: str) -> bool:
        if len(s1) > len(s2):
            return False
        need, win = [0] * 26, [0] * 26
        m = len(s1)
        for i in range(m):
            need[ord(s1[i]) - 97] += 1
            win[ord(s2[i]) - 97] += 1
        if need == win:
            return True
        for i in range(m, len(s2)):
            win[ord(s2[i]) - 97] += 1
            win[ord(s2[i - m]) - 97] -= 1
            if need == win:
                return True
        return False

class Solution:
    def minWindow(self, s: str, t: str) -> str:
        if not t or not s:
            return ''
        need = Counter(t)
        win = {}
        have, req = 0, len(need)
        best_len, best_span = float('inf'), (0, 0)
        l = 0
        for r, ch in enumerate(s):
            win[ch] = win.get(ch, 0) + 1
            if ch in need and win[ch] == need[ch]:
                have += 1
            while have == req:
                if (r - l + 1) < best_len:
                    best_len = r - l + 1
                    best_span = (l, r + 1)
                left_ch = s[l]
                win[left_ch] -= 1
                if left_ch in need and win[left_ch] < need[left_ch]:
                    have -= 1
                l += 1
        return '' if best_len == float('inf') else s[best_span[0]:best_span[1]]

class Solution:
    def maxSlidingWindow(self, nums: List[int], k: int) -> List[int]:
        dq = deque()
        res = []
        for i, x in enumerate(nums):
            while dq and dq[0] <= i - k:
                dq.popleft()
            while dq and nums[dq[-1]] <= x:
                dq.pop()
            dq.append(i)
            if i >= k - 1:
                res.append(nums[dq[0]])
        return res

class Solution:
    def isValid(self, s: str) -> bool:
        pairs = {')': '(', ']': '[', '}': '{'}
        stack = []
        for ch in s:
            if ch in pairs:
                if not stack or stack.pop() != pairs[ch]:
                    return False
            else:
                stack.append(ch)
        return not stack

