        return fleets

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        stack = []
        best = 0
        for i, h in enumerate(heights):
            start = i
            while stack and stack[-1][1] > h:
                idx, ph = stack.pop()
                best = max(best, ph * (i - idx))
                start = idx
            stack.append((start, h))
        n = len(heights)
        for idx, ph in stack:
            best = max(best, ph * (n - idx))
        return best

