class Codec:
    def serialize(self, root: Optional[TreeNode]) -> str:
        vals = []
        def dfs(n):
            if not n:
                vals.append('#')
                return
            vals.append(str(n.val))
            dfs(n.left)
            dfs(n.right)
        dfs(root)
        return ','.join(vals)
    def deserialize(self, data: str) -> Optional[TreeNode]:
        toks = iter(data.split(','))
        def build():
            t = next(toks)
            if t == '#':
                return None
            n = TreeNode(int(t))
            n.left = build()
            n.right = build()
            return n
        return build()

