        adj = defaultdict(list)
        indeg = [0] * numCourses
        for crs, pre in prerequisites:
            adj[pre].append(crs)
            indeg[crs] += 1
        q = deque(i for i in range(numCourses) if indeg[i] == 0)
        done = 0
        while q:
            u = q.popleft()
            done += 1
            for v in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        return done == numCourses

