        starts = sorted(iv[0] for iv in intervals)
        ends = sorted(iv[1] for iv in intervals)
        s = e = cnt = best = 0
        while s < len(intervals):
            if starts[s] < ends[e]:
                s += 1
                cnt += 1
                best = max(best, cnt)
            else:
