class LFUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.kv = {}
        self.freqs = defaultdict(OrderedDict)
        self.min_f = 0
    def _touch(self, key, new_val=None):
        v, f = self.kv[key]
        if new_val is not None:
            v = new_val
        del self.freqs[f][key]
        if not self.freqs[f] and f == self.min_f:
            self.min_f += 1
        self.freqs[f + 1][key] = None
        self.kv[key] = (v, f + 1)
        return v
    def get(self, key: int) -> int:
        return self._touch(key) if key in self.kv else -1
    def put(self, key: int, value: int) -> None:
        if self.cap <= 0:
            return
        if key in self.kv:
            self._touch(key, value)
            return
        if len(self.kv) == self.cap:
            evict_k, _ = self.freqs[self.min_f].popitem(last=False)
            del self.kv[evict_k]
        self.kv[key] = (value, 1)
        self.freqs[1][key] = None
        self.min_f = 1

