from collections import deque

def bfs_order(graph: dict[int, list[int]], start: int) -> list[int]:
    q = deque([start])
    visited = {start}
    order = []
    while q:
        u = q.popleft()
        order.append(u)
        for v in graph.get(u, []):
            if v not in visited:
                visited.add(v)
                q.append(v)
    return order

import heapq

def top_k_sorted_desc(nums: list[int], k: int) -> list[int]:
    h = []
    for x in nums:
        heapq.heappush(h, x)
        if len(h) > k:
            heapq.heappop(h)
    return sorted(h, reverse=True)

def combine_k(nums: list[int], k: int) -> list[list[int]]:
    res, path = [], []
    def dfs(start):
        if len(path) == k:
            res.append(path[:])
            return
        for i in range(start, len(nums)):
            path.append(nums[i])
            dfs(i + 1)
            path.pop()
    dfs(0)
    return res

def region_area(grid: list[list[int]], sr: int, sc: int) -> int:
    R, C = len(grid), len(grid[0])
    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] != 1:
            return 0
        grid[r][c] = 0
        return 1 + dfs(r+1,c) + dfs(r-1,c) + dfs(r,c+1) + dfs(r,c-1)
    return dfs(sr, sc)

def max_non_adjacent_sum(nums: list[int]) -> int:
    p2 = p1 = 0
    for x in nums:
        p2, p1 = p1, max(p2 + x, p1)
    return p1
